using System;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// 심전도 고리 한가운데 신체 실루엣. 머리 / 상체 / 팔 / 다리가 간격으로 나뉜 앞모습.
/// 멀쩡하면 올리브색, 눈(머리)·팔·다리가 파손되면 그 부위만 빨강.
/// </summary>
public class BodyHeartsUI : MonoBehaviour
{
    const int W = 96;
    const int H = 232;
    const float ViewW = 52f;
    const float ViewH = 126f;

    enum Limb { None, Head, Body, Arm, Leg }

    static readonly Color32 Clear = new Color32(0, 0, 0, 0);
    static readonly Color32 Flesh = new Color32(88, 88, 72, 255);
    static readonly Color32 Hurt = new Color32(214, 46, 40, 255);

    const string MaskB64 = "";

    Image figure;
    Texture2D tex;
    Sprite sprite;
    Limb[] mask;
    Color32[] pixels;
    PlayerBodyStatus status;
    RectTransform heartRate;
    int shown = -1;

    void Awake()
    {
        byte[] raw = Convert.FromBase64String(MaskB64);
        mask = new Limb[W * H];
        for (int i = 0; i < mask.Length; i++) mask[i] = (Limb)raw[i];
        pixels = new Color32[W * H];

        tex = new Texture2D(W, H, TextureFormat.RGBA32, false)
        {
            filterMode = FilterMode.Bilinear,
            wrapMode = TextureWrapMode.Clamp,
            hideFlags = HideFlags.HideAndDontSave
        };
        Paint(false, false, false);
        sprite = Sprite.Create(tex, new Rect(0, 0, W, H), new Vector2(0.5f, 0.5f), 100f);
        sprite.hideFlags = HideFlags.HideAndDontSave;

        var go = new GameObject("Body", typeof(RectTransform), typeof(Image));
        go.transform.SetParent(transform, false);
        var rt = (RectTransform)go.transform;
        rt.anchorMin = Vector2.zero;
        rt.anchorMax = Vector2.one;
        rt.offsetMin = Vector2.zero;
        rt.offsetMax = Vector2.zero;
        figure = go.GetComponent<Image>();
        figure.sprite = sprite;
        figure.raycastTarget = false;
        figure.color = Color.white;
    }

    void OnDestroy()
    {
        if (sprite != null) Destroy(sprite);
        if (tex != null) Destroy(tex);
    }

    void LateUpdate()
    {
        PlaceInsideHeartRing();
        if (status == null)
        {
            status = FindFirstObjectByType<PlayerBodyStatus>();
            if (status == null) return;
        }

        int key = (status.EyePenalty ? 1 : 0) | (status.ArmPenalty ? 2 : 0) | (status.LegPenalty ? 4 : 0);
        if (key == shown) return;
        shown = key;
        Paint(status.EyePenalty, status.ArmPenalty, status.LegPenalty);
    }

    void PlaceInsideHeartRing()
    {
        if (heartRate == null)
        {
            var ui = GameObject.Find("HeartRateUI");
            if (ui == null) return;
            heartRate = ui.GetComponent<RectTransform>();
            transform.SetSiblingIndex(heartRate.GetSiblingIndex() + 1);
        }

        var rt = (RectTransform)transform;
        rt.anchorMin = rt.anchorMax = new Vector2(1f, 1f);
        rt.pivot = new Vector2(0.5f, 0.5f);
        rt.sizeDelta = new Vector2(ViewW, ViewH);
        rt.anchoredPosition = heartRate.anchoredPosition + new Vector2(
            (0.5f - heartRate.pivot.x) * heartRate.sizeDelta.x,
            (0.5f - heartRate.pivot.y) * heartRate.sizeDelta.y);
    }

    void Paint(bool eye, bool arm, bool leg)
    {
        for (int y = 0; y < H; y++)
        {
            for (int x = 0; x < W; x++)
            {
                int i = y * W + x;
                Limb part = mask[i];
                if (part == Limb.None)
                {
                    pixels[i] = Clear;
                    continue;
                }

                bool hurt = (part == Limb.Head && eye) || (part == Limb.Arm && arm) || (part == Limb.Leg && leg);
                pixels[i] = Tint(hurt ? Hurt : Flesh, ShadeAt(x, y) * Grain(x, y));
            }
        }

        tex.SetPixels32(pixels);
        tex.Apply(false);
    }

    static Color32 Tint(Color32 color, float shade)
    {
        return new Color32(
            (byte)Mathf.Clamp(Mathf.RoundToInt(color.r * shade), 0, 255),
            (byte)Mathf.Clamp(Mathf.RoundToInt(color.g * shade), 0, 255),
            (byte)Mathf.Clamp(Mathf.RoundToInt(color.b * shade), 0, 255),
            color.a);
    }

    float ShadeAt(int x, int y)
    {
        float shade = 1f;
        if (!Filled(x, y + 1)) shade *= 1.08f;
        if (!Filled(x - 1, y)) shade *= 1.04f;
        if (!Filled(x, y - 1)) shade *= 0.78f;
        if (!Filled(x + 1, y)) shade *= 0.88f;
        return shade;
    }

    static float Grain(int x, int y)
    {
        int h = x * 374761393 + y * 668265263;
        h = (h ^ (h >> 13)) * 1274126177;
        h ^= h >> 16;
        return 0.94f + (h & 255) / 255f * 0.10f;
    }

    bool Filled(int x, int y)
    {
        if ((uint)x >= W || (uint)y >= H) return false;
        return mask[y * W + x] != Limb.None;
    }
}